class InvalidSwVersion(Exception):
    """ Raised when SW version is invalid. """
    pass


class DownloadProcedureError(Exception):
    """ Raised when SW download command failed after retries """
    pass


class IncorrectPackageChecksum(Exception):
    """ Raised when expected software package checksum does not match actual checksum """
    pass


class NotEnoughSpace(Exception):
    """
    Raised when there is not enough space on disk.
    """
    pass


class SwVersionsDoNotMatch(Exception):
    """
    Raised when software version is not equal to expected software version.
    """
